        self.game_server_inventory.bind();
        self.timeline.bind();
        self.video.bind();
        self.parental_settings.bind();
        self.remote_play.bind();
        self.networking_messages.bind();
        self.game_server_networking_messages.bind();
        self.networking_sockets.bind();
